INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('451b5082-6f9b-4db2-a420-d5feaeb017f3', '21feff02-016d-46e2-bb9d-c27495133b1b', '91. óra: Feladatmegoldás', 'Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cc12ca12-b4fd-4bf9-93a1-3af6325b8eb0", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "3b159ccc-c83d-4cd2-ab84-8126bd604921", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "22d572b5-67df-4f78-999d-ef5dd5595889", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "071b383e-9957-44cc-b6a2-01b207836427", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "fd8d4ae6-c304-47c0-a8bd-ca7cfd649877", "text": "Igaz", "isCorrect": true}, {"id": "3e84828f-c793-4919-918e-0a4ce6df2ad1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ce680fc9-be2a-4409-bb84-96179e5022db", "text": "Melyik egyenlet írja le: ''Egy szám 4-szeresénél 5-tel több a 25''? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "6e911426-5c6c-4c1a-98de-cf4fddd1c68b", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "9eb49f3d-a216-4dc1-9e56-88706d2d5589", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "0b3971ae-b90d-4ce9-993b-ac6fbe8df234", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "61fdfcfa-c918-4038-9265-7ca48ac1d8c3", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "12ef7bf8-c488-43e7-9f3b-012e7911be60", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "836ad4c5-a9f2-4608-a9f3-049927fad774", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "37361841-36cc-4d0a-888e-737266a58cf7", "text": "Igaz", "isCorrect": true}, {"id": "dd66ac3c-ec62-4462-8d97-db63c49a5dfc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('41fc0d35-2b65-4a10-af88-c2ba9b4a8fe5', '21feff02-016d-46e2-bb9d-c27495133b1b', '92. óra: Több megoldás is lehet', 'Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bbf7601f-bf42-4371-9341-8de3f3b6d5e6", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "137b561c-d03a-402e-93fe-0952660e8e2c", "text": "Mely kifejezés jelenti azt, hogy ''legfeljebb 5''?", "type": "multiple-choice", "options": [{"id": "2eb995ba-168f-4341-8e44-63085f54c26d", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "cac62210-1c7e-4b59-85b2-a2cb0dfb4b15", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "3932518d-1147-430a-8195-f3cada3b6841", "text": "Pontosan 5", "isCorrect": false}, {"id": "745a4a3e-c1cf-46ae-b4ae-9c50793ee0e0", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "d4d0df6b-3e0a-410b-b71b-18d6f42c3ad1", "text": "Mely kifejezés jelenti azt, hogy ''legalább 5''?", "type": "multiple-choice", "options": [{"id": "e87117c2-1848-45d5-9360-c9e808162d29", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "064b393b-4bcc-47a7-872c-bf6b5f14eb5e", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "43af5e0f-fadc-4cd9-8b6f-1d58654621ec", "text": "Pontosan 5", "isCorrect": false}, {"id": "46a1f978-061d-404b-bc02-d4564e7a42a9", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "feb661e4-03a5-4b08-b48c-692577e3ac06", "text": "A ''legalább 3 és legfeljebb 6'' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "681ebd8a-3634-4800-8e60-de7a3cee5076", "text": "Igaz", "isCorrect": true}, {"id": "f9475802-89ac-426d-8cf2-9be6037b0582", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bdcbd7f2-ed6a-4c33-93b9-c5af9a2f89ce", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "c1eed371-37bc-4ab7-8dea-0f160661535f", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "b745cf03-1781-4cbe-beeb-28eb702ec153", "text": "Igaz", "isCorrect": true}, {"id": "55496f50-0de4-458f-9248-fe79a9d0c2cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "edfbc277-0a87-4012-a086-62c5bb3ee2f5", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2aa71a74-2c12-4f8e-bd97-3ec025ce051a', '21feff02-016d-46e2-bb9d-c27495133b1b', '93. óra: Létraverseny II.', 'Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "32d9de7c-b758-4e7d-aee7-31172c58036a", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "7443550e-d187-4abe-bade-56dbb2466cb3", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8a450880-1bc8-428c-a02e-d69791bcf48f", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "684f9236-62c4-4644-a7ec-ac63cf398914", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "4d9780e9-4fe8-4058-baba-727a9f41d40f", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "bd1bf5b9-b8a3-4571-a629-474a47a3e3d7", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "a6d58c62-d3a4-4ba3-96d0-7c8d4c51ed51", "text": "Igaz", "isCorrect": true}, {"id": "f334d9c4-0f51-409c-9813-99dd991e23a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3024edc2-0362-4487-8138-e66e665eeb31", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('30712c3f-f65e-47a5-aa39-49a8999ed27a', '21feff02-016d-46e2-bb9d-c27495133b1b', '94. óra: Összefoglalás', 'A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "f8390045-2362-4266-ad47-26a6d3a11da2", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "7bc627b7-7375-466f-9169-d3675e727adc", "text": "1 : 3", "isCorrect": true}, {"id": "98a1c723-c3b7-425a-a1e8-abb40f09e3ec", "text": "1 : 4", "isCorrect": false}, {"id": "9f3445cd-8c9f-46f4-9f20-2b9f87a43871", "text": "2 : 3", "isCorrect": false}, {"id": "2fe77019-dfff-44a3-a771-c6b506cfde4b", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "316c0d47-2b6b-49f1-af57-d0b63bf51b26", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "76926458-3c06-44a8-a3ea-a993cf521d80", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "454e585e-169d-4040-b7fb-9b25ce552ce0", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "3a95528f-da47-4000-af9a-176e26098a3e", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "cc56ae4f-b3ed-4c53-a60d-922881116ccc", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "16dfee07-e389-417d-96ff-c6b020e017a9", "text": "Igaz", "isCorrect": true}, {"id": "bf09e492-2934-419b-bb69-176840e531b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d8fe5e59-4770-449a-95a9-9a62a8ad7b10", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('35262c7d-0819-4a65-835d-64cf04190043', '21feff02-016d-46e2-bb9d-c27495133b1b', '95. óra: Gyakorlóóra', 'Gyakorló feladatok önállóan, becslés és ellenőrzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "2f27bc2a-00c1-435a-b600-921a03a2cb65", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "9eeef3f9-0966-4fa9-bbcd-fb4175e4ac23", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "68195868-4e0d-4d89-90ff-e439c32602d3", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "8bc0d428-437d-4a7e-9b89-07aa1b759dbc", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "3863d31b-a6cb-4fa7-abf3-d858e05fb150", "text": "Igaz", "isCorrect": true}, {"id": "dad05a1f-341a-4648-9f08-6262e74bebdf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "493941be-801b-4d7f-8d15-95f0ec93f1ab", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "814f65ba-5bc4-48e4-9d5b-997747819944", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "806d6296-b252-4b09-abc2-ff2145e61e17", "text": "Igaz", "isCorrect": true}, {"id": "8f3548fb-e4fd-41c2-b7df-72a85d493c54", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "723cd58f-24a4-4021-b023-5890d0d6553d", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ede3ab54-7b88-4ae5-bcc2-ccf848054be3', '21feff02-016d-46e2-bb9d-c27495133b1b', '96. óra: Témazáró dolgozat', 'Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "120dd518-63e0-49de-8b4c-5974b1ac9a87", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "1240a66c-dcb8-4b59-a3c3-7c81b29f13cd", "text": "2 : 7", "isCorrect": true}, {"id": "306df9fc-e182-4710-bcf6-706eca9ea948", "text": "1 : 35", "isCorrect": false}, {"id": "ec0d8ceb-2630-4b22-95e9-0a52a43ce57c", "text": "2 : 5", "isCorrect": false}, {"id": "a1074362-0e1e-4cce-81ea-7c687efecfd6", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "349a58f0-5ce7-4ab3-a2da-969a28d3ccab", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "d8e9950e-95c4-4c68-9302-848ef206164b", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "20630b47-db56-42d0-ab7b-e8616b77ce8c", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "2b0a53a4-e310-4f96-ab42-aa47492b4bfe", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "35b599a2-586c-47b6-82d9-33885988246b", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "0b947fd9-e6d8-4271-98b8-85fd3acadb64", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "b396b427-3efd-4a68-85fe-718a7ffa438b", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "17806f7c-c7b0-42f3-a5ce-12607c6edff6", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "53f43fe8-a3dd-415f-b450-32c27065d275", "text": "Igaz", "isCorrect": true}, {"id": "af59aed1-aac0-486e-81ce-fe32fd2e5979", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "60e3f5c9-0a13-4fb8-9659-f391626aab39", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d1db03b1-dacc-4418-a191-b6192874f0e7', '21feff02-016d-46e2-bb9d-c27495133b1b', '97. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "807ba1c6-77d9-4013-a5af-35aefcde2d0b", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "a8f8c18d-5970-493a-bc82-63365e010d15", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "178ae48f-6f97-4e9c-87a0-f96ecafb6619", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "6c9f3dd5-20f0-4472-a2ee-963666a3a717", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "36062966-c954-481f-a4d6-3d57400cc5fb", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "e9dda588-97da-4d41-b7f5-49a502af0b1c", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "d9dc5d2b-4e93-460b-939e-bbe54c55b8d6", "text": "Igaz", "isCorrect": true}, {"id": "595d5981-ad1f-438d-8912-8684ebf574bb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c24889d-808d-4972-b739-6236377b14be", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "6e794178-417a-4283-bf31-dfc220e602c6", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "eb5d9ca4-7643-4f76-8644-6e37b601d574", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "c215482c-8e40-4b28-8ae3-ea7cd1631ef5", "text": "Igaz", "isCorrect": true}, {"id": "169c0b02-8aae-4dfd-815a-2f4d81bd73a1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "160006d1-de1a-4e53-a05f-50f0e9e26161", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "67e2fc81-a21f-4afd-a284-decbb0211c3b", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('30694def-1dd9-4bd3-b215-10f28ab300f5', '21feff02-016d-46e2-bb9d-c27495133b1b', '98. óra: Hosszúság, tömeg, idő', 'A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "53928b6c-d86f-4b38-b987-fddde9d4efce", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "afe3bac5-0d35-42a5-a955-3602b31ab639", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "208571d4-3577-448f-ba7c-695e11847550", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "d9b600a1-3515-4a89-b29c-d4dcdb693308", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "30a0d052-955e-4148-93c4-7576b98256c2", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "a0a942bb-b7e9-4270-b68a-71ffe8ef45f6", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "850fe4f0-6860-40ba-8f3b-d4a9bb9ed131", "text": "Igaz", "isCorrect": true}, {"id": "1f0e6d43-6cbc-4b4f-9a68-9cff0113094d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "82a8f2ec-1e57-48e2-9235-32d8a2d9f430", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b8291482-5172-4336-8b62-bf376b0d60ba', '21feff02-016d-46e2-bb9d-c27495133b1b', '99. óra: Hosszúság, tömeg, idő II.', 'Összetett mértékegység-átváltási feladatok és gyakorlás.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b61b02de-ad6d-4704-a88b-1f76023bdc1c", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "dd247af3-5cf8-4fcc-9bcb-b611f4b795d4", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "408afbb6-2bc0-46db-9de7-63bc0bde1d91", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "1f0c314c-1beb-4eca-b761-21d3010b5007", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "43b484cd-48fe-4fe8-9c7a-adcd47c80191", "text": "Igaz", "isCorrect": true}, {"id": "f6df839f-b568-4781-acba-ca3a91e562e3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ad285ca-e9bb-4216-b6d0-5da9fde2f3ec", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "69d192f3-bf6d-4490-a732-9137d90f2b9f", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "1acf577d-a42e-4feb-a655-adf96ab1c079", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "3bff09d7-a847-45e3-bc63-7234832052f3", "text": "Igaz", "isCorrect": true}, {"id": "18afc548-662d-4284-b122-ea5066e46a0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9d5502fd-671c-41c3-bc7a-4b727b9b74c6', '21feff02-016d-46e2-bb9d-c27495133b1b', '100. óra: A sokszögek kerülete', 'Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "a7bb1fc2-c6dd-4796-b03a-ab9fa7698dea", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "9a7e8915-bcdd-4eb0-a9ac-1fd32f047920", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "db28465c-edcb-40e8-acf5-7afbda73afec", "text": "K = a * b", "isCorrect": false}, {"id": "36d9ebca-a320-474c-b607-bc4f80af9f0a", "text": "K = a + b", "isCorrect": false}, {"id": "3ca77f53-f4fe-4a0a-9c86-e77f92614192", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "706236d7-2166-458e-ac80-63ee37d10dd2", "text": "Mi a négyzet kerületének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "8b8a1ecd-1a9c-44f9-8183-5ba82277e5e4", "text": "K = 4 * a", "isCorrect": true}, {"id": "ad65989b-fdf2-4723-b083-3e133093ab00", "text": "K = a * a", "isCorrect": false}, {"id": "54e70860-ddf3-4e23-adc8-74b9b52e1f7f", "text": "K = 2 * a", "isCorrect": false}, {"id": "9702cfdf-d205-4ef9-819d-01b8437efa4f", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "5ecfa139-ecd4-4256-b1a4-ff70b473209e", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "36a4bfeb-0822-4d5f-8fb5-68d797e09b59", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "55603f3e-71a9-45e9-8e28-5563a8acbef2", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "77db3b4a-4d1e-4110-8391-61f979a39c8f", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "7782d6f4-dd48-4679-a31e-ab72ef2a87a6", "text": "Igaz", "isCorrect": true}, {"id": "b32712d3-d882-41e4-8a7d-29e9100204fd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cb09b2b3-f48d-4698-8f7c-98fd15344271", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;